 "content": "def transform(grid):
    """Restore masked cells in a framed, row-shifted periodic color field."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find the longest intact horizontal run in the patterned interior.
    best = None
    for r in range(3, h):
        c = 3
        while c < w:
            while c < w and grid[r][c] == 0:
                c += 1
            start = c
            while c < w and grid[r][c] != 0:
                c += 1
            if best is None or c - start > best[0]:
                if c > start:
                    best = (c - start, r, start, grid[r][start:c])
    if best is None:
        return out

    length, seed_r, seed_c, run = best
    # The source run repeats with the shortest exact period (the larger
    # candidates are multiples of the actual cycle).
    period = length
    for p in range(2, length + 1):
        if all(run[i] == run[i % p] for i in range(length)):
            period = p
            break
    cycle = run[:period]

    # Relative row phase is determined by the visible cells in that row.
    phases = {}
    for r in range(3, h):
        scores = []
        for shift in range(period):
            matches = 0
            for c in range(3, w):
                v = grid[r][c]
                if v != 0 and v == cycle[(c - seed_c + shift) % period]:
                    matches += 1
            scores.append(matches)
        phases[r] = max(range(period), key=lambda s: scores[s])

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r <= 1:
                out[r][c] = 1
            elif r == 2:
                out[r][c] = 4 if c >= 2 else 1
            elif c < 2:
                out[r][c] = 1
            elif c == 2:
                out[r][c] = 4
            else:
                out[r][c] = cycle[(c - seed_c + phases[r]) % period]
    return out
